const productQuestStateCounts = `-- name: ProductQuestStateCounts :many
WITH filtered AS (
    SELECT q.status
    FROM quests q
    JOIN members dm ON dm.id = q.dm_id
    WHERE q.deleted_at IS NULL
      AND ($1::uuid IS NULL OR EXISTS (SELECT 1 FROM quest_arcs a WHERE a.id = q.arc_id AND a.public_id = $1::uuid))
      AND ($2::uuid IS NULL OR dm.public_id = $2::uuid)
      AND ($3::text IS NULL OR q.kinds @> ARRAY[$3::text]::text[])
      AND ($4::uuid IS NULL OR EXISTS (
          SELECT 1 FROM quest_regions qr JOIN regions r ON r.id = qr.region_id
          WHERE qr.quest_id = q.id AND r.public_id = $4::uuid
      ))
      AND (NOT $5::boolean OR q.tags && $6::text[])
      AND (NOT $7::boolean OR q.genres && $8::text[])
), counts AS (
    SELECT 'open'::text AS state, 1 AS sort_order, count(*) FILTER (WHERE status = 'open')::bigint AS count FROM filtered
    UNION ALL SELECT 'full'::text, 2, count(*) FILTER (WHERE status = 'full')::bigint FROM filtered
    UNION ALL SELECT 'played'::text, 3, count(*) FILTER (WHERE status = 'played')::bigint FROM filtered
    UNION ALL SELECT 'closed'::text, 4, count(*) FILTER (WHERE status = 'closed')::bigint FROM filtered
    UNION ALL SELECT 'cancelled'::text, 5, count(*) FILTER (WHERE status = 'cancelled')::bigint FROM filtered
)
SELECT state, count FROM counts ORDER BY sort_order
`

type ProductQuestStateCountsParams struct {
	ArcID          pgtype.UUID `json:"arc_id"`
	DmID           pgtype.UUID `json:"dm_id"`
	Kind           string      `json:"kind"`
	RegionID       pgtype.UUID `json:"region_id"`
	TagFilterSet   bool        `json:"tag_filter_set"`
	TagVariants    []string    `json:"tag_variants"`
	GenreFilterSet bool        `json:"genre_filter_set"`
	GenreVariants  []string    `json:"genre_variants"`
}

type ProductQuestStateCountsRow struct {
	State string `json:"state"`
	Count int64  `json:"count"`
}

